node - <<'NODE'
const fs=require('fs'),crypto=require('crypto');const sha=p=>crypto.createHash('sha256').update(fs.readFileSync(p)).digest('hex');
const path='docs/remediation/design/W25.01/baseline.json',b=JSON.parse(fs.readFileSync(path));
const owned=new Set(b.owned.map(x=>x.path)),protectedPins=b.pins.filter(x=>!owned.has(x.path));
const mismatches=protectedPins.filter(x=>sha(x.path)!==x.sha256).map(x=>x.path);
console.log(JSON.stringify({final_source_stop:{at:new Date().toISOString(),files:[...owned].map(path=>({path,sha256:sha(path)}))},protected_source_comparison:{expected:protectedPins.length,matched:protectedPins.length-mismatches.length,mismatches},references:[path,'docs/remediation/design/W25.01/plan.md','docs/remediation/evidence/W25.01/admission.json'].map(path=>({path,sha256:sha(path)}))},null,2));if(mismatches.length)process.exitCode=1;
NODE
